4d\u0928 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915\u094b\u0902 \u092a\u0930 \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f (inference latency) \u092c\u0922\u093c\u093e\u0924\u093e \u0939\u0948?\n\n---\n\n## 1. \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093e \u0924\u0930\u094d\u0915\u0938\u0902\u0917\u0924 \u0906\u0927\u093e\u0930 (Rationale) \u0914\u0930 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930\n\n### 1.1 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092a\u0943\u0937\u094d\u0920\u092d\u0942\u092e\u093f \u0914\u0930 \u092a\u094d\u0930\u0947\u0930\u0923\u093e\n\u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 (single-query) \u0935\u093f\u0927\u093f\u092f\u093e\u0901 \u091c\u0948\u0938\u0947 **Expert Prompting** (\u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e \u092d\u0942\u092e\u093f\u0915\u093e/\u0928\u093f\u0930\u094d\u0926\u0947\u0936 \u0906\u0927\u093e\u0930\u093f\u0924 \u0938\u0940\u0927\u093e \u0905\u0928\u0941\u092e\u093e\u0928) \u0914\u0930 **PAL (Program-Aided Language models)** (\u0915\u094b\u0921 \u091c\u0928\u0930\u0947\u091f \u0915\u0930 \u0907\u0902\u091f\u0930\u092a\u094d\u0930\u0947\u091f\u0930 \u0938\u0947 \u0917\u0923\u0928\u093e \u0915\u0930\u093e\u0928\u093e) \u0915\u0947\u0935\u0932 \u090f\u0915 \u092e\u0941\u0916\u094d\u092f LLM \u0915\u0949\u0932 \u092e\u0947\u0902 \u0938\u092e\u0938\u094d\u092f\u093e \u0939\u0932 \u0915\u0930\u0928\u0947 \u0915\u093e \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0924\u0940 \u0939\u0948\u0902\u0964 \u0907\u0938\u0915\u0947 \u0935\u093f\u092a\u0930\u0940\u0924, **Buffer of Thoughts (BoT)** \u090f\u0915 \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f-\u0938\u0902\u0935\u0930\u094d\u0927\u093f\u0924 (thought-augmented) \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u093e \u0939\u0948 \u091c\u093f\u0938\u092e\u0947\u0902 \u0924\u0940\u0928 \u092e\u0941\u0916\u094d\u092f \u0918\u091f\u0915 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902:\n1. **Problem Distiller**: \u0907\u0928\u092a\u0941\u091f \u0938\u092e\u0938\u094d\u092f\u093e \u0938\u0947 \u092e\u0947\u091f\u093e-\u0935\u093f\u0936\u0947\u0937\u0924\u093e\u090f\u0902 \u0914\u0930 \u092c\u093e\u0927\u093e\u090f\u0902 (constraints) \u0928\u093f\u0915\u093e\u0932\u0928\u093e\u0964\n2. **Template Retriever**: \u092a\u0942\u0930\u094d\u0935-\u0928\u093f\u0930\u094d\u092e\u093f\u0924 'Meta-Buffer' \u0938\u0947 \u0938\u092c\u0938\u0947 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u0935\u093f\u091a\u093e\u0930-\u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f (thought template) \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u093e\u0964\n3. **Thought-Instantiated Reasoner**: \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u0938\u092e\u0938\u094d\u092f\u093e \u0915\u093e \u0938\u092e\u093e\u0927\u093e\u0928 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0928\u093e\u0964\n\n\u092f\u0926\u094d\u092f\u092a\u093f BoT \u0915\u094b Tree-of-Thoughts (ToT) \u092f\u093e Graph-of-Thoughts (GoT) \u091c\u0948\u0938\u0940 \u092d\u093e\u0930\u0940 \u092c\u0939\u0941-\u0915\u094d\u0935\u0947\u0930\u0940 (multi-query) \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0915\u0941\u0936\u0932 \u092e\u093e\u0928\u093e \u0917\u092f\u093e \u0939\u0948, \u092a\u0930\u0902\u0924\u0941 \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0907\u0938\u0915\u093e \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u092c\u0922\u093c \u0938\u0915\u0924\u093e \u0939\u0948 \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u0907\u0938\u092e\u0947\u0902 \u0921\u093f\u0938\u094d\u091f\u093f\u0932\u0947\u0936\u0928 \u0914\u0930 \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f \u0907\u0928\u0938\u094d\u091f\u0948\u0928\u0936\u093f\u090f\u0936\u0928 \u0915\u0947 \u091a\u0930\u0923 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902\u0964 \u092f\u0939 \u092a\u094d\u0930\u092f\u094b\u0917 \u0928\u093f\u0937\u094d\u092a\u0915\u094d\u0937 \u0930\u0942\u092a \u0938\u0947 \u092f\u0939 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e BoT \u0915\u093e \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0913\u0935\u0930\u0939\u0947\u0921 \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u0935\u0943\u0926\u094d\u0927\u093f \u0915\u093e \u0915\u093e\u0930\u0923 \u092c\u0928\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 2. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0938\u0947\u091f\u0905\u092a (Experimental Setup)\n\n### 2.1 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u0921\u0947\u091f\u093e\u0938\u0947\u091f\u094d\u0938\n\u092a\u094d\u0930\u092f\u094b\u0917 \u0924\u0940\u0928 \u0935\u093f\u0935\u093f\u0927 \u0921\u094b\u092e\u0947\u0928 \u0915\u0947 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915\u094b\u0902 \u092a\u0930 \u0938\u0902\u091a\u093e\u0932\u093f\u0924 \u0939\u094b\u0917\u093e:\n1. **Game of 24** (\u0917\u0923\u093f\u0924\u0940\u092f \u0916\u094b\u091c \u090f\u0935\u0902 \u092f\u094b\u091c\u0928\u093e): \n   - 100 \u0938\u0947 1,362 \u092e\u093e\u0928\u0915 \u0938\u092e\u0938\u094d\u092f\u093e\u090f\u0902 (\u0915\u0920\u093f\u0928\u093e\u0908 \u0930\u0948\u0902\u0915 1 \u0938\u0947 1362)\u0964\n   - \u092a\u094d\u0930\u0915\u0943\u0924\u093f: \u0938\u0940\u092e\u093f\u0924 \u0930\u093e\u091c\u094d\u092f-\u0938\u094d\u0925\u093e\u0928 (bounded state space) \u0916\u094b\u091c\u0964\n2. **MGSM (Multilingual Grade School Math)** (\u092c\u0939\u0941\u092d\u093e\u0937\u0940 \u0924\u0930\u094d\u0915):\n   - 250 \u092c\u0939\u0941\u092d\u093e\u0937\u0940 \u092a\u094d\u0930\u0936\u094d\u0928 (\u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u092d\u093e\u0937\u093e\u0913\u0902 \u091c\u0948\u0938\u0947 \u0905\u0902\u0917\u094d\u0930\u0947\u091c\u0940, \u091a\u0940\u0928\u0940, \u0938\u094d\u092a\u0947\u0928\u093f\u0936, \u091c\u0930\u094d\u092e\u0928 \u0906\u0926\u093f \u092e\u0947\u0902)\u0964\n   - \u092a\u094d\u0930\u0915\u0943\u0924\u093f: \u092c\u0939\u0941-\u091a\u0930\u0923\u0940\u092f \u0936\u093e\u092c\u094d\u0926\u093f\u0915 \u0917\u0923\u093f\u0924\u0940\u092f \u0938\u092e\u0938\u094d\u092f\u093e \u0938\u092e\u093e\u0927\u093e\u0928\u0964\n3. **Checkmate-in-One** (\u0938\u094d\u0925\u093e\u0928\u093f\u0915 \u090f\u0935\u0902 \u0928\u093f\u092f\u092e-\u0906\u0927\u093e\u0930\u093f\u0924 \u092a\u0939\u0947\u0932\u0940):\n   - FEN (Forsyth-Edwards Notation) \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u092e\u0947\u0902 1,000 \u0936\u0924\u0930\u0902\u091c \u092a\u0939\u0947\u0932\u093f\u092f\u093e\u0901\u0964\n   - \u092a\u094d\u0930\u0915\u0943\u0924\u093f: \u0938\u094d\u0925\u093e\u0928\u093f\u0915 \u091c\u094d\u092f\u093e\u092e\u093f\u0924\u093f \u0914\u0930 \u0928\u093f\u092f\u092e-\u092c\u0926\u094d\u0927 \u0924\u093e\u0930\u094d\u0915\u093f\u0915 \u0935\u0948\u0927\u0924\u093e\u0964\n\n### 2.2 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u0935\u093f\u0927\u093f\u092f\u093e\u0901 (Evaluated Frameworks)\n1. **Buffer of Thoughts (BoT)**:\n   - *Problem Distillation*: \u0907\u0928\u092a\u0941\u091f \u0938\u092e\u0938\u094d\u092f\u093e \u0915\u093e \u0938\u0902\u0915\u094d\u0937\u0947\u092a\u0923 \u0914\u0930 \u092a\u094d\u0930\u092e\u0941\u0916 \u091a\u0930 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923 (\u0939\u0932\u094d\u0915\u0947 \u092f\u093e \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092e\u0949\u0921\u0932 \u0926\u094d\u0935\u093e\u0930\u093e)\u0964\n   - *Template Retrieval*: \u092e\u0947\u091f\u093e-\u092c\u092b\u0930 \u0938\u0947 \u0915\u094b\u0938\u093e\u0907\u0928 \u0938\u093f\u092e\u093f\u0932\u0948\u0930\u093f\u091f\u0940 / \u090f\u092e\u094d\u092c\u0947\u0921\u093f\u0902\u0917-\u0906\u0927\u093e\u0930\u093f\u0924 \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f \u092e\u0948\u091a\u093f\u0902\u0917\u0964\n   - *Thought-Instantiated Reasoning*: \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f \u0914\u0930 \u0921\u093f\u0938\u094d\u091f\u093f\u0932\u094d\u0921 \u0907\u0928\u092a\u0941\u091f \u0915\u0947 \u0938\u093e\u0925 \u092e\u0941\u0916\u094d\u092f \u0930\u0940\u091c\u0928\u0930 \u0926\u094d\u0935\u093e\u0930\u093e \u0909\u0924\u094d\u0924\u0930 \u0909\u0924\u094d\u092a\u093e\u0926\u0928\u0964\n2. **Expert Prompting (Single-query baseline 1)**:\n   - \u0921\u094b\u092e\u0947\u0928-\u0935\u093f\u0936\u093f\u0937\u094d\u091f '\u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e' \u0938\u093f\u0938\u094d\u091f\u092e \u092a\u094d\u0930\u0949\u092e\u094d\u092a\u094d\u091f (\u0909\u0926\u093e. *\"You are a world-class chess master / mathematician...\"*) \u0915\u0947 \u0938\u093e\u0925 \u0938\u0940\u0927\u0947 \u0938\u092e\u093e\u0927\u093e\u0928 \u0915\u0940 \u090f\u0915\u0932 \u0915\u094d\u0935\u0947\u0930\u0940\u0964\n3. **PAL (Program-Aided Language models) (Single-query baseline 2)**:\n   - \u0938\u092e\u0938\u094d\u092f\u093e \u0915\u094b \u0939\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u0902\u0930\u091a\u093f\u0924 Python \u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0928\u0947 \u0939\u0947\u0924\u0941 \u090f\u0915\u0932 \u0915\u094d\u0935\u0947\u0930\u0940, \u091c\u093f\u0938\u0947 \u0938\u0948\u0902\u0921\u092c\u0949\u0915\u094d\u0938 \u0915\u093f\u090f \u0917\u090f Python 3.10 \u0907\u0902\u091f\u0930\u092a\u094d\u0930\u0947\u091f\u0930 \u092e\u0947\u0902 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u0930 \u092a\u0930\u093f\u0923\u093e\u092e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n4. **Standard Chain-of-Thought (CoT)** *(\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0938\u0902\u0926\u0930\u094d\u092d)*:\n   - \u092e\u093e\u0928\u0915 'Step-by-step' \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u0906\u0927\u093e\u0930\u092d\u0942\u0924 \u0938\u0902\u0926\u0930\u094d\u092d\u0964\n\n### 2.3 \u0915\u0902\u092a\u094d\u092f\u0942\u091f \u090f\u0935\u0902 \u092e\u0949\u0921\u0932 \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 (Compute & Model Specifications)\n- **\u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092c\u0948\u0915\u092c\u094b\u0928 LLM**: `Llama-3-70B-Instruct` (\u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0915\u094d\u0932\u0938\u094d\u091f\u0930 \u092a\u0930) \u092f\u093e `GPT-4o / GPT-4-turbo` (API \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947)\u0964\n  - \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092a\u0930\u093f\u0928\u093f\u092f\u094b\u091c\u0928 \u0915\u094b \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915\u0924\u093e \u0926\u0940 \u091c\u093e\u090f\u0917\u0940 (vLLM \u0907\u0902\u091c\u0928, 2x/4x NVIDIA A100-80GB GPUs) \u0924\u093e\u0915\u093f \u092c\u093e\u0939\u0930\u0940 \u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u0905\u0938\u094d\u0925\u093f\u0930\u0924\u093e \u0914\u0930 \u0938\u0930\u094d\u0935\u0930 \u0932\u094b\u0921 \u092e\u0947\u0902 \u0909\u0924\u093e\u0930-\u091a\u0922\u093c\u093e\u0935 \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u092e\u093e\u092a \u0915\u094b \u0935\u093f\u0915\u0943\u0924 \u0928 \u0915\u0930\u0947\u0902\u0964\n- **\u0939\u093e\u0907\u092a\u0930\u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938**:\n  - `Temperature = 0.0` (Greedy decoding: \u0917\u0948\u0930-\u0928\u093f\u092f\u0924\u093e\u0924\u094d\u092e\u0915\u0924\u093e \u0914\u0930 \u091f\u094b\u0915\u0928 \u0932\u0902\u092c\u093e\u0908 \u092e\u0947\u0902 \u0905\u0928\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u092d\u093f\u0928\u094d\u0928\u0924\u093e \u0938\u092e\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f)\u0964\n  - `Top_p = 1.0`, `Max_tokens = 1024`\u0964\n  - `Batch Size = 1` (\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0915\u094d\u0935\u0947\u0930\u0940 \u0915\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u090f\u0902\u0921-\u091f\u0942-\u090f\u0902\u0921 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0915\u094b \u0938\u091f\u0940\u0915 \u0930\u0942\u092a \u0938\u0947 \u092a\u0943\u0925\u0915 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f)\u0964\n\n---\n\n## 3. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Experimental Controls) \u0914\u0930 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938\n\n### 3.1 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Rigorous Controls)\n1. **\u0938\u092e\u093e\u0928 \u0907\u0928\u092a\u0941\u091f \u0907\u0902\u0938\u094d\u091f\u0947\u0902\u0938**: \u0938\u092d\u0940 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u0938\u0947 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0938\u092e\u093e\u0928 \u0915\u094d\u0930\u092e \u0914\u0930 \u092a\u094d\u0930\u0936\u094d\u0928\u094b\u0902 \u0915\u093e \u0938\u0947\u091f \u0926\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n2. **\u0911\u092b\u0932\u093e\u0907\u0928 \u092c\u0928\u093e\u092e \u0911\u0928\u0932\u093e\u0907\u0928 \u092a\u0943\u0925\u0915\u094d\u0915\u0930\u0923**: BoT \u0915\u0947 'Meta-Buffer' \u0915\u094b \u092a\u094d\u0930\u092f\u094b\u0917 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0911\u092b\u093c\u0932\u093e\u0907\u0928 \u0924\u0948\u092f\u093e\u0930 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964 \u092c\u092b\u0930 \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0938\u092e\u092f \u0915\u094b \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u092e\u0947\u0902 \u0928\u0939\u0940\u0902 \u0917\u093f\u0928\u093e \u091c\u093e\u090f\u0917\u093e; \u0915\u0947\u0935\u0932 \u091f\u0947\u0938\u094d\u091f-\u091f\u093e\u0907\u092e \u0911\u0928\u0932\u093e\u0907\u0928 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u092e\u093e\u092a\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n3. **\u091f\u093e\u0907\u092e\u093f\u0902\u0917 \u092c\u093e\u0909\u0902\u0921\u094d\u0930\u0940 \u0915\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0930\u0923 (Standardized Timing Boundaries)**:\n   - \u0909\u091a\u094d\u091a-\u092a\u0930\u093f\u0936\u0941\u0926\u094d\u0927\u0924\u093e \u091f\u093e\u0907\u092e\u0930 (`time.perf_counter_ns()`) \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n   - **BoT Total Latency** = $t_{\\text{distill}} + t_{\\text{retrieve}} + t_{\\text{reasoning}}$\n   - **PAL Total Latency** = $t_{\\text{llm\\_generation}} + t_{\\text{python\\_execution}}$\n   - **Expert Total Latency** = $t_{\\text{llm\\_generation}}$\n4. **\u0935\u093e\u0930\u094d\u092e-\u0905\u092a \u0930\u0928 (Warm-up Runs)**: GPU \u0915\u0930\u094d\u0928\u0947\u0932 \u0914\u0930 \u0915\u0948\u0936 \u0935\u093e\u0930\u094d\u092e-\u0905\u092a \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u092a\u0930 \u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 5 \u0921\u092e\u0940 \u092a\u094d\u0930\u0936\u094d\u0928\u094b\u0902 \u0915\u094b \u092e\u093e\u092a \u0938\u0947 \u092c\u093e\u0939\u0930 \u0930\u0916\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n5. **\u092a\u0941\u0928\u0930\u093e\u0935\u0943\u0924\u094d\u0924\u093f (Repetition)**: \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u094b 3 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0926\u094c\u0921\u093c\u094b\u0902 (runs) \u092e\u0947\u0902 \u0926\u094b\u0939\u0930\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0914\u0930 \u0914\u0938\u0924 \u0926\u0930\u094d\u091c \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n### 3.2 \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u090f\u0935\u0902 \u0926\u094d\u0935\u093f\u0924\u0940\u092f\u0915 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938\n1. **\u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Latency Metrics)**:\n   - **\u0914\u0938\u0924 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 (Mean Latency per Problem)** (\u0938\u0947\u0915\u0902\u0921 \u092e\u0947\u0902)\u0964\n   - **\u092e\u0940\u0921\u093f\u092f\u0928 \u090f\u0935\u0902 IQR (Median and Interquartile Range Latency)** (\u0906\u0909\u091f\u0932\u093e\u092f\u0930\u094d\u0938 \u0915\u0947 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u094b \u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f)\u0964\n   - **P95 / P99 \u0932\u0947\u091f\u0947\u0902\u0938\u0940** (\u091f\u0947\u0932-\u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923)\u0964\n2. **\u0918\u091f\u0915-\u0938\u094d\u0924\u0930\u0940\u092f \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u092c\u094d\u0930\u0947\u0915\u0921\u093e\u0909\u0928 (Component Breakdown)**:\n   - BoT: \u0921\u093f\u0938\u094d\u091f\u093f\u0932\u0947\u0936\u0928 \u0938\u092e\u092f, \u090f\u092e\u094d\u092c\u0947\u0921\u093f\u0902\u0917 \u0930\u093f\u091f\u094d\u0930\u0940\u0935\u0932 \u0938\u092e\u092f, \u0930\u0940\u091c\u0928\u0930 \u091c\u0928\u0930\u0947\u0936\u0928 \u0938\u092e\u092f\u0964\n   - PAL: \u0915\u094b\u0921 \u091c\u0928\u0930\u0947\u0936\u0928 \u0938\u092e\u092f \u092c\u0928\u093e\u092e \u0915\u094b\u0921 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0938\u092e\u092f\u0964\n3. **\u0938\u0902\u0938\u093e\u0927\u0928 \u090f\u0935\u0902 \u091f\u094b\u0915\u0928 \u0916\u092a\u0924 (Resource Metrics)**:\n   - \u0914\u0938\u0924 \u0907\u0928\u092a\u0941\u091f (Prompt) \u091f\u094b\u0915\u0928 \u0914\u0930 \u0906\u0909\u091f\u092a\u0941\u091f (Completion) \u091f\u094b\u0915\u0928\u0964\n   - \u0915\u0941\u0932 API \u0915\u0949\u0932\u094d\u0938 / \u092b\u0949\u0930\u0935\u0930\u094d\u0921 \u092a\u093e\u0938\u0947\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u092a\u094d\u0930\u0924\u093f \u0938\u092e\u0938\u094d\u092f\u093e\u0964\n4. **\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u092e\u0947\u091f\u094d\u0930\u093f\u0915 (Task Accuracy / Solve Rate)**:\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u092a\u0930 \u0938\u091f\u0940\u0915\u0924\u093e \u0926\u0930 (%) \u0924\u093e\u0915\u093f \u092f\u0939 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0939\u094b \u0938\u0915\u0947 \u0915\u093f \u0917\u0924\u093f \u092e\u0947\u0902 \u0915\u094b\u0908 \u092d\u0940 \u0905\u0902\u0924\u0930 \u0938\u092e\u093e\u0927\u093e\u0928 \u0915\u0940 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u092f\u093e \u091f\u094b\u0915\u0928 \u091f\u094d\u0930\u0902\u0915\u0947\u0936\u0928 \u0938\u0947 \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964\n\n---\n\n## 4. \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Analysis Plan) \u0914\u0930 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u092a\u0930\u0940\u0915\u094d\u0937\u0923\n\n### 4.1 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (Hypothesis Testing)\n- **\u0936\u0942\u0928\u094d\u092f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e ($H_0$)**: BoT \u0915\u093e \u0914\u0938\u0924 \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u0935\u093f\u0927\u093f (Expert / PAL) \u0915\u0947 \u092c\u0930\u093e\u092c\u0930 \u092f\u093e \u0909\u0938\u0938\u0947 \u0915\u092e \u0939\u0948\u0964\n  $$\\mu_{\\text{time}}(\\text{BoT}) \\le \\mu_{\\text{time}}(\\text{Method})$$\n- **\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e ($H_1$)**: BoT \u0915\u093e \u0914\u0938\u0924 \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u0935\u093f\u0927\u093f \u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u0948\u0964\n  $$\\mu_{\\text{time}}(\\text{BoT}) > \\mu_{\\text{time}}(\\text{Method})$$\n\n### 4.2 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0927\u093f\u092f\u093e\u0901\n1. **\u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0938\u094d\u0925\u093f\u0924\u093f \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (Normality Test)**: \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0905\u0902\u0924\u0930 \u0935\u093f\u0924\u0930\u0923 \u092a\u0930 Shapiro-Wilk \u092a\u0930\u0940\u0915\u094d\u0937\u0923\u0964\n2. **\u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (Comparative Significance)**:\n   - \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0935\u093f\u0924\u0930\u0923 \u0939\u094b\u0928\u0947 \u092a\u0930: **Paired Student\u2019s t-test** (\u090f\u0915-\u0924\u0930\u092b\u093e)\u0964\n   - \u0917\u0948\u0930-\u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092f\u093e \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0935\u093f\u0937\u092e (skewed) \u0939\u094b\u0928\u0947 \u092a\u0930: **Wilcoxon Signed-Rank Test**\u0964\n   - $p < 0.01$ \u0915\u094b \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u092e\u093e\u0928\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n3. **\u092a\u094d\u0930\u092d\u093e\u0935 \u0906\u0915\u093e\u0930 (Effect Size)**: Cohen's $d$ \u092f\u093e Wilcoxon $r$ \u092a\u094d\u0930\u092d\u093e\u0935 \u0906\u0915\u093e\u0930 \u0915\u0940 \u0917\u0923\u0928\u093e, \u091c\u093f\u0938\u0938\u0947 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0935\u0943\u0926\u094d\u0927\u093f \u0915\u0947 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u092e\u0939\u0924\u094d\u0935 \u0915\u093e \u0906\u0915\u0932\u0928 \u0939\u094b \u0938\u0915\u0947\u0964\n4. **\u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915-\u0935\u093e\u0930 \u092c\u0939\u0941-\u0915\u093e\u0930\u0915 \u0924\u0941\u0932\u0928\u093e (Multi-Factor Analysis)**:\n   - \u0926\u094b-\u0924\u0930\u092b\u093c\u093e \u090f\u0928\u094b\u0935\u093e (Two-Way ANOVA) \u092f\u093e LMM (Linear Mixed-Effects Model):\n     $$\\text{Latency} \\sim \\text{Method} + \\text{Benchmark} + (\\text{Method} \\times \\text{Benchmark}) + (1|\\text{Instance})$$\n     \u092f\u0939 \u092f\u0939 \u091c\u093e\u0902\u091a\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e \u0907\u0928\u092b\u0930\u0947\u0902\u0938 \u0938\u092e\u092f \u092e\u0947\u0902 \u0935\u0943\u0926\u094d\u0927\u093f \u091f\u093e\u0938\u094d\u0915 \u0915\u0947 \u092a\u094d\u0930\u0915\u093e\u0930 (\u091c\u0948\u0938\u0947 \u0936\u0924\u0930\u0902\u091c \u092c\u0928\u093e\u092e \u0917\u0923\u093f\u0924) \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964\n5. **\u091f\u094b\u0915\u0928-\u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0938\u0939\u0938\u0902\u092c\u0902\u0927 (Token Correlation Analysis)**:\n   - \u0915\u094d\u092f\u093e BoT \u0915\u0940 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u094d\u0930\u0949\u092e\u094d\u092a\u094d\u091f \u091f\u094b\u0915\u0928 \u0915\u0947 \u0915\u093e\u0930\u0923 \u092c\u0922\u093c\u0940 \u0939\u0948 \u092f\u093e \u0921\u093f\u0938\u094d\u091f\u093f\u0932\u0947\u0936\u0928 \u0915\u0947 \u0926\u094b\u0939\u0930\u0947 \u0915\u0949\u0932 \u0915\u0947 \u0915\u093e\u0930\u0923, \u0907\u0938\u0915\u093e \u092a\u093f\u092f\u0930\u094d\u0938\u0928/\u0938\u094d\u092a\u0940\u092f\u0930\u092e\u0948\u0928 \u0938\u0939\u0938\u0902\u092c\u0902\u0927 \u0926\u094d\u0935\u093e\u0930\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923\u0964\n\n---\n\n## 5. \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e (Feasibility) \u0914\u0930 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0909\u092a\u093e\u092f\n\n1. **\u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e**: \n   - \u090f\u0915\u0932-\u0915\u094d\u0935\u0947\u0930\u0940 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0914\u0930 BoT \u092e\u0947\u0902 ToT (Tree-of-Thoughts) \u0915\u0940 \u0924\u0930\u0939 \u0938\u0948\u0915\u0921\u093c\u094b\u0902 \u0936\u093e\u0916\u093e\u0913\u0902 \u0915\u0940 \u0916\u094b\u091c \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u0940\u0964 BoT \u092e\u0947\u0902 \u0915\u0947\u0935\u0932 2 LLM \u0915\u0949\u0932\u094d\u0938 (\u0921\u093f\u0938\u094d\u091f\u093f\u0932\u0947\u0936\u0928 + \u0930\u0940\u091c\u093c\u0928\u093f\u0902\u0917) \u0924\u0925\u093e 1 \u0935\u0947\u0915\u094d\u091f\u0930 \u0930\u093f\u091f\u094d\u0930\u0940\u0935\u0932 \u0939\u094b\u0924\u093e \u0939\u0948\u0964 \u0905\u0924\u0903 \u092f\u0939 \u092a\u094d\u0930\u092f\u094b\u0917 \u092e\u0927\u094d\u092f\u092e \u0915\u0902\u092a\u094d\u092f\u0942\u091f \u0938\u0902\u0938\u093e\u0927\u0928\u094b\u0902 (\u091c\u0948\u0938\u0947 1 \u0938\u0947 2 GPU \u0935\u0930\u094d\u0915\u0938\u094d\u091f\u0947\u0936\u0928) \u092a\u0930 24-48 \u0918\u0902\u091f\u094b\u0902 \u0915\u0947 \u092d\u0940\u0924\u0930 \u092a\u0942\u0930\u094d\u0923\u0924\u0903 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n2. **\u0938\u0948\u0902\u0921\u092c\u0949\u0915\u094d\u0938 \u0938\u0941\u0930\u0915\u094d\u0937\u093e (PAL \u0915\u0947 \u0932\u093f\u090f)**:\n   - PAL \u0915\u0947 \u0915\u094b\u0921 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0915\u0947 \u0932\u093f\u090f \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0935\u093e\u0924\u093e\u0935\u0930\u0923 (\u091c\u0948\u0938\u0947 `RestrictedPython` \u092f\u093e Docker \u0915\u0902\u091f\u0947\u0928\u0930) \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u091c\u093f\u0938\u092e\u0947\u0902 CPU \u091f\u093e\u0907\u092e\u0906\u0909\u091f (5 \u0938\u0947\u0915\u0902\u0921) \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0939\u094b\u0917\u093e \u0924\u093e\u0915\u093f \u0907\u0928\u092b\u093f\u0928\u093f\u091f \u0932\u0942\u092a\u094d\u0938 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u092e\u093e\u092a \u0915\u094b \u0926\u0942\u0937\u093f\u0924 \u0928 \u0915\u0930\u0947\u0902\u0964\n3. **\u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e**:\n   - Game of 24, MGSM, \u0914\u0930 Checkmate-in-One \u0938\u093e\u0930\u094d\u0935\u091c\u0928\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0909\u092a\u0932\u092c\u094d\u0927 \u092e\u093e\u0928\u0915 \u0905\u0915\u093e\u0926\u092e\u093f\u0915 \u092c\u0947\u0902\u091a\u092e\